# Fix the region finding - need separate visited sets per color
grid = [
    [0, 0, 0, 0, 0, 0, 0],
    [0, 4, 4, 4, 4, 4, 4],
    [0, 4, 6, 6, 6, 6, 6],
    [0, 4, 6, 2, 2, 2, 2],
    [0, 4, 6, 2, 6, 6, 6],
    [0, 4, 6, 2, 6, 2, 2],
    [0, 4, 6, 2, 6, 2, 4]
]

from collections import deque

def find_regions(grid):
    h, w = len(grid), len(grid[0])
    regions = {}

    directions = [(0,1), (0,-1), (1,0), (-1,0)]

    for color in set(val for row in grid for val in row):
        visited = set()

        for r in range(h):
            for c in range(w):
                if grid[r][c] == color and (r,c) not in visited:
                    region_cells = []
                    queue = deque([(r,c)])
                    visited.add((r,c))

                    while queue:
                        cr, cc = queue.popleft()
                        region_cells.append((cr, cc))

                        for dr, dc in directions:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))

                    regions[color] = sorted(region_cells, key=lambda x: (x[0], x[1]))

    return regions

regions = find_regions(grid)
print("Regions by color:")
for color in sorted(regions.keys()):
    cells = regions[color]
    print(f"\nColor {color}: {len(cells)} cells")
    for r, c in cells:
        print(f"  ({r},{c})")

