# Submit sorted-by-value rings (using second-most-frequent color for each ring)
grid = [
    [0, 0, 0, 0, 0, 0, 0],
    [0, 4, 4, 4, 4, 4, 4],
    [0, 4, 6, 6, 6, 6, 6],
    [0, 4, 6, 2, 2, 2, 2],
    [0, 4, 6, 2, 6, 6, 6],
    [0, 4, 6, 2, 6, 2, 2],
    [0, 4, 6, 2, 6, 2, 4]
]

ring_nums = [[min(r, c, 6-r, 6-c) for c in range(7)] for r in range(7)]

from collections import defaultdict
ring_counts = {rnum: defaultdict(int) for rnum in range(4)}
for r in range(7):
    for c in range(7):
        ring_counts[ring_nums[r][c]][grid[r][c]] += 1

# Second most frequent color per ring
ring_second = {}
for rnum in range(4):
    counts = dict(ring_counts[rnum])
    # Get all colors and sort by count descending
    sorted_colors = sorted(counts.items(), key=lambda x: -x[1])
    # Most frequent is first, second most is second
    if len(sorted_colors) > 1:
        ring_second[rnum] = sorted_colors[1][0]
    else:
        ring_second[rnum] = sorted_colors[0][0]  # fallback to single color

print("Second most frequent per ring:")
for rnum in range(4):
    print(f"Ring {rnum}: {ring_second[rnum]}")

output_second_freq = []
for r in range(7):
    new_row = []
    for c in range(7):
        rnum = ring_nums[r][c]
        new_row.append(ring_second[rnum])
    output_second_freq.append(new_row)

action = {"action": "submit", "grid": output_second_freq}
print(f"\nSubmitting second freq: {json.dumps(action)}")
